<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {Sparkles,RefreshCw,Square,Check,History} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document,type ProgressAnchor} from '../domain/local-contract'
import type {WritingPreferences} from './preferences'
import type {WritingRun} from './contract'
import type {WritingDirectionPlan} from './planning-contract'
import {prepareDirectionWriting,executeWritingAction} from './actions-runtime'
import {keepWritingDirections,saveWritingDirectionChoices,copyWritingDirectionPlan} from './planning-runtime'
import {slotModel} from '../repositories/local-models'
import {recoverWriting,stopWriting,writingPendingView,retryWritingSave,hasPendingWritingSave} from './runtime'
const props=defineProps<{storyId:string;anchor:ProgressAnchor|null;direction:string;once:Partial<WritingPreferences>;selectedPlanId?:string|null;disabled?:boolean}>(),emit=defineEmits<{choose:[value:{id:string;direction:string}];view:[id:string];pending:[value:boolean]}>(),store=useLocal()
const opened=ref(false),busy=ref(false),error=ref(''),plans=ref<Document<WritingDirectionPlan>[]>([]),requests=ref<Document<WritingRun>[]>([]),current=ref<Document<WritingDirectionPlan>|null>(null),task=ref<Document<WritingRun>|null>(null),choices=ref<WritingDirectionPlan['choices']>([]),pending=ref(0),durable=ref('[]'),hydrating=ref(false),conflict=ref(false)
const matching=computed(()=>requests.value.filter(r=>canonical(r.value.anchor)===canonical(props.anchor))),saved=computed(()=>pending.value===0&&JSON.stringify(choices.value)===durable.value)
const sourcePlans=(runId:string)=>plans.value.filter(p=>p.value.runId===runId).sort((a,b)=>a.value.createdAt.localeCompare(b.value.createdAt)||a.id.localeCompare(b.id))
const history=computed(()=>matching.value.flatMap(run=>{const copies=sourcePlans(run.id);return copies.length?copies.map((plan,index)=>({id:index?plan.id:run.id,label:new Date(plan.value.createdAt).toLocaleString()+' · '+plan.value.choices[0]!.title+(index?' · 副本':'')})):[{id:run.id,label:new Date(run.value.createdAt).toLocaleString()+' · '+(run.value.status==='running'?'正在想':'未完成')}]}))
const historyId=computed(()=>current.value?(sourcePlans(current.value.value.runId)[0]?.id===current.value.id?current.value.value.runId:current.value.id):task.value?.id)
let disposed=false,epoch=0,work=Promise.resolve();const states=new Map<string,{row:Document<WritingDirectionPlan>;durable:string}>()
function show(row:Document<WritingDirectionPlan>){current.value=row;hydrating.value=true;choices.value=JSON.parse(JSON.stringify(row.value.choices));durable.value=JSON.stringify(row.value.choices);states.set(row.id,{row,durable:durable.value});hydrating.value=false;const index=plans.value.findIndex(p=>p.id===row.id);if(index<0)plans.value.unshift(row);else plans.value[index]=row;task.value=requests.value.find(r=>r.id===row.value.runId)||null;conflict.value=false;emit('view',row.id)}
function showRun(row:Document<WritingRun>){if(disposed||store.vault?.unlocked!==true)return;task.value=row;const index=requests.value.findIndex(r=>r.id===row.id);if(index<0)requests.value.unshift(row);else requests.value[index]=row}
function saveDraft(){const row=current.value,vault=store.vault,buffer=JSON.parse(JSON.stringify(choices.value)) as WritingDirectionPlan['choices'];if(!row||!vault||hydrating.value||disposed)return work;const state=states.get(row.id)!;pending.value++;const job=work.catch(()=>{}).then(async()=>{if(JSON.stringify(buffer)===state.durable)return;if(conflict.value)throw new Error('另一窗口已改过这组方向，可另存我的输入');const savedRow=await saveWritingDirectionChoices(vault,state.row,buffer);state.row=savedRow;state.durable=JSON.stringify(buffer);if(!disposed&&store.vault===vault){const index=plans.value.findIndex(p=>p.id===row.id);if(index<0)plans.value.unshift(savedRow);else plans.value[index]=savedRow;if(current.value?.id===row.id){current.value=savedRow;durable.value=state.durable}}});work=job.finally(()=>pending.value--);void work.catch(e=>{if(!disposed){error.value=(e as Error).message;if((e as {code?:string}).code==='REVISION_CONFLICT')conflict.value=true}});return work}
watch(choices,()=>{if(!hydrating.value)void saveDraft()},{deep:true,flush:'sync'})
watch([pending,saved],()=>emit('pending',!saved.value))
async function load(){const vault=store.vault,ticket=++epoch;if(!vault)return;const all=await vault.list<WritingRun|WritingDirectionPlan>('settings');if(disposed||store.vault!==vault||ticket!==epoch)return;requests.value=(all.filter(r=>r.value.assetType==='writing-run'&&(r.value as WritingRun).purpose?.kind==='directions'&&(r.value as WritingRun).storyId===props.storyId) as Document<WritingRun>[]).sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));for(const row of matching.value)if(row.value.status==='running')showRun(await recoverWriting(vault,row));if(disposed||ticket!==epoch||store.vault!==vault)return;plans.value=(all.filter(r=>r.value.assetType==='writing-directions'&&r.value.storyId===props.storyId) as Document<WritingDirectionPlan>[]).sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));const preferred=plans.value.find(p=>p.id===props.selectedPlanId&&matching.value.some(r=>r.id===p.value.runId)),latest=matching.value[0];if(preferred)show(preferred);else if(latest){task.value=latest;const plan=plans.value.find(p=>p.value.runId===latest.id);if(plan)show(plan);else if(latest.value.status==='completed'){const created=await keepWritingDirections(vault,latest.id);if(!disposed&&ticket===epoch&&store.vault===vault)show(created)}}}
watch(opened,open=>{if(open)void load().catch(e=>error.value=(e as Error).message)})
async function generate(){const vault=store.vault,anchor=props.anchor,ticket=epoch;if(!vault||!anchor||busy.value||props.disabled)return;busy.value=true;error.value='';try{await saveDraft();await work;const prepared=await prepareDirectionWriting(vault,await slotModel(vault,'text'),anchor,props.direction,props.once);current.value=null;hydrating.value=true;choices.value=[];durable.value='[]';hydrating.value=false;showRun(prepared);const result=await executeWritingAction(vault,prepared.id,row=>{if(!disposed&&store.vault===vault)showRun(writingPendingView(vault,row))});if(!disposed&&ticket===epoch&&store.vault===vault){showRun(result);if(result.value.status==='completed'&&!hasPendingWritingSave(vault,result.id))show(await keepWritingDirections(vault,result.id))}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function choose(index:number){if(busy.value||props.disabled)return;try{await saveDraft();await work;const row=current.value;if(row)emit('choose',{id:row.id,direction:choices.value[index]!.direction})}catch(e){error.value=(e as Error).message}}
async function chooseHistory(id:string){const vault=store.vault,ticket=epoch;if(busy.value||!vault)return;try{await saveDraft();await work;const cached=plans.value.find(p=>p.id===id)||sourcePlans(id)[0],plan=cached?await vault.read<WritingDirectionPlan>(cached.id):null;if(disposed||ticket!==epoch||store.vault!==vault||!opened.value)return;if(cached){if(plan?.kind!=='settings'||plan.value.assetType!=='writing-directions'||plan.value.storyId!==props.storyId||plan.value.runId!==cached.value.runId)throw new Error('这份方向记录已失效，当前输入保留');show(plan)}else{const row=requests.value.find(r=>r.id===id);if(row){task.value=row;current.value=null;hydrating.value=true;choices.value=[];durable.value='[]';hydrating.value=false}}}catch(e){if(!disposed)error.value=(e as Error).message}}
async function copyDraft(){const vault=store.vault,row=current.value;if(!vault||!row||busy.value)return;try{await work.catch(()=>{});show(await copyWritingDirectionPlan(vault,row,choices.value));error.value=''}catch(e){error.value=(e as Error).message}}
async function retrySave(){const vault=store.vault,row=task.value;if(!vault||!row)return;try{showRun(await retryWritingSave(vault,row.id));if(task.value?.value.status==='completed')show(await keepWritingDirections(vault,row.id));error.value=''}catch(e){error.value=(e as Error).message}}
async function flush(){await saveDraft();await work}
defineExpose({flush})
onUnmounted(()=>{disposed=true;epoch++})
</script>
<template><section class="final-directions"><button type="button" :aria-expanded="opened" :disabled="disabled" @click="opened=!opened"><Sparkles :size="16"/>找三个走向</button><div v-if="opened" class="final-directions-body"><div class="final-directions-toolbar"><button type="button" :disabled="busy||disabled" @click="generate"><RefreshCw :size="16"/>{{matching.length?'重新想一组':'生成三个方向'}}</button><button v-if="busy&&task" type="button" @click="store.vault&&stopWriting(store.vault,task.id)"><Square :size="15"/>停止</button><select v-if="matching.length" aria-label="选择方向生成记录" :value="historyId" :disabled="busy" @change="chooseHistory(($event.target as HTMLSelectElement).value)"><option v-for="row in history" :key="row.id" :value="row.id">{{row.label}}</option></select></div><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="conflict" type="button" @click="copyDraft">另存我的输入</button><div v-if="current" class="final-direction-cards"><article v-for="(choice,index) in choices" :key="choice.id"><span class="final-direction-number">0{{index+1}}</span><label>方向标题<input v-model="choice.title" :aria-label="'方向 '+(index+1)+' 标题'" maxlength="100" :disabled="busy||disabled"></label><label>走向<textarea v-model="choice.direction" :aria-label="'方向 '+(index+1)+' 走向'" maxlength="20000" rows="3" :disabled="busy||disabled"/></label><details><summary>决定与后果</summary><p>{{current.value.original[index]?.decision}}</p><p>{{current.value.original[index]?.conflict}}</p><p>{{current.value.original[index]?.consequence}}</p></details><button type="button" :disabled="busy||disabled||conflict" @click="choose(index)"><Check :size="16"/>用这个方向</button></article><small role="status">{{saved?'方向已保存':'正在保存方向…'}}</small></div><p v-else-if="busy" role="status">正在想三个走向…</p><p v-else-if="task" role="status">{{task.value.error||'这次方向未完成，可直接填写故事走向。'}}</p><button v-if="task&&store.vault&&hasPendingWritingSave(store.vault,task.id)" type="button" @click="retrySave">只重试保存</button><details v-if="task?.value.chapters[0]?.raw"><summary><History :size="15"/>原返回</summary><pre>{{task.value.chapters[0]?.raw}}</pre></details></div></section></template>
<style scoped>
.final-directions-body{display:grid;gap:16px;margin-top:16px}.final-directions-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.final-directions-toolbar select{max-width:100%;flex:1;min-width:140px}.final-direction-cards{display:grid;gap:12px}.final-direction-cards article{display:grid;gap:12px;position:relative;border:1px solid var(--edge);border-radius:14px;padding:16px;background:var(--paper)}.final-direction-number{font:14px var(--font-ui);color:var(--accent);letter-spacing:.1em}.final-direction-cards label{display:grid;gap:8px;font-size:13px;color:var(--quiet)}.final-direction-cards input{font:20px var(--font-reading,serif)}.final-direction-cards textarea{font:16px/1.6 var(--font-reading,serif)}.final-direction-cards details,.final-direction-cards small{font-size:12px;color:var(--quiet)}.final-directions pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:30dvh;overflow:auto}.final-direction-cards article>button{justify-self:end;color:var(--accent)}
</style>
